// Извлекаем информацию о вакансиях и объединяем для анализа ВСЕХ сразу
const vacanciesData = [];
let allVacanciesCombined = '';

// Проверяем, что пришли данные
if (!Array.isArray(items) || items.length === 0) {
  return [{
    json: {
      error: "Нет данных для обработки",
      all_vacancies_combined: "",
      total_vacancies_count: 0,
      current_date: new Date().toLocaleDateString('ru-RU')
    }
  }];
}

// Обрабатываем входные данные
const inputData = Array.isArray(items[0].json) ? items[0].json : items.map(item => item.json);

for (let i = 0; i < inputData.length; i++) {
  const vacancy = inputData[i];

  // Извлекаем все доступные данные
  const vacancyInfo = {
    id: vacancy.id,
    name: vacancy.name,
    requirement_text: vacancy.snippet?.requirement || '',
    responsibility_text: vacancy.snippet?.responsibility || '',
    key_skills: vacancy.key_skills || [],
    professional_roles: vacancy.professional_roles?.map(role => role.name) || [],
    experience: vacancy.experience?.name || '',
    schedule: vacancy.schedule?.name || '',
    employer_name: vacancy.employer?.name || '',
    published_at: vacancy.published_at || '',
    full_description_url: vacancy.url || ''
  };

  // Очищаем HTML теги
  vacancyInfo.requirement_clean = vacancyInfo.requirement_text
    .replace(/<[^>]*>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();

  vacancyInfo.responsibility_clean = vacancyInfo.responsibility_text
    .replace(/<[^>]*>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();

  // Объединяем все тексты для отдельной вакансии
  vacancyInfo.combined_text_for_ai = `
    Должность: ${vacancyInfo.name}
    Требования: ${vacancyInfo.requirement_clean}
    Обязанности: ${vacancyInfo.responsibility_clean}
    ${vacancyInfo.key_skills.length > 0 ? 'Ключевые навыки: ' + vacancyInfo.key_skills.map(skill => typeof skill === 'object' ? skill.name : skill).join(', ') : ''}
    Опыт: ${vacancyInfo.experience}
    Специализация: ${vacancyInfo.professional_roles.join(', ')}
  `.trim();

  // Добавляем вакансию к общему тексту (ВСЕ вакансии вместе)
  allVacanciesCombined += `=== ВАКАНСИЯ ${i + 1} ===
Название: ${vacancyInfo.name}
Требования: ${vacancyInfo.requirement_clean}
Обязанности: ${vacancyInfo.responsibility_clean}
${vacancyInfo.key_skills.length > 0 ? 'Ключевые навыки: ' + vacancyInfo.key_skills.map(skill => typeof skill === 'object' ? skill.name : skill).join(', ') : ''}
Опыт: ${vacancyInfo.experience}
Специализация: ${vacancyInfo.professional_roles.join(', ')}
Работодатель: ${vacancyInfo.employer_name}

`;

  vacanciesData.push(vacancyInfo);
}

// Возвращаем данные для GigaChat
return [{
  json: {
    // Для анализа ВСЕХ вакансий сразу
    all_vacancies_combined: allVacanciesCombined.trim(),
    total_vacancies_count: vacanciesData.length,
    current_date: new Date().toLocaleDateString('ru-RU'),

    // Для отладки/проверки
    debug_info: {
      vacancies_processed: vacanciesData.length,
      sample_vacancy_name: vacanciesData[0]?.name || 'нет',
      combined_text_length: allVacanciesCombined.length
    }
  }
}];
